static vk_texture textures[VK_MAX_TEXTURES];
/* PS2_PERF_NATIVE_STORE (ov_cpu 2026-10-25; default 1; 0 = as before): a native region with new pixels looks for an old
   slot of the same place to take over (ps2_vk_texture_native_k) by a scan over every texture slot; the scan read one
   field of each ~200-byte slot (1,600 slots in M2: a strided walk through ~300 KB per store), and the new pixels were
   copied twice (source -> scratch -> the slot's spare buffer; 1 MB each for a 512 x 512 atlas region). The places now
   also live in a dense array scanned first (the same slots in the same order, the same choice), and a taken-over slot
   gets the pixels straight from the source. The same slots, pixels and uploads. */
static u64 tex_place_of[VK_MAX_TEXTURES];
static u32 ntextures;

#define TEX_HASH 4096u
static s32 tex_head[TEX_HASH], tex_tail[TEX_HASH], tex_next[VK_MAX_TEXTURES];
static int tex_index_ready;

static u32 tex_bucket(u64 key) { return (u32)((key * 0x9E3779B97F4A7C15ull) >> 52); }

static s32 tex_first(u64 key) {
    if (!tex_index_ready) return -1;
    return tex_head[tex_bucket(key)];
}

static void tex_index_remove(u32 i) {
    u32 b = tex_bucket(textures[i].key);
    s32 prev = -1;
    for (s32 c = tex_head[b]; c >= 0; prev = c, c = tex_next[c]) {
        if (c != (s32)i) continue;
        if (prev >= 0) tex_next[prev] = tex_next[c]; else tex_head[b] = tex_next[c];
        if (tex_tail[b] == c) tex_tail[b] = prev;
        tex_next[c] = -1;
        return;
    }
}
static void tex_index_add(u32 i) {
    u32 b;
    if (!tex_index_ready) {
        for (u32 k = 0; k < TEX_HASH; k++) tex_head[k] = tex_tail[k] = -1;
        tex_index_ready = 1;
    }
    b = tex_bucket(textures[i].key);
    tex_next[i] = -1;
    if (tex_tail[b] >= 0) tex_next[tex_tail[b]] = (s32)i;
    else tex_head[b] = (s32)i;
    tex_tail[b] = (s32)i;
}
static size_t tex_bytes;
static s32 tex_uploading = -1;          /* texture whose CPU pixels the renderer is copying to staging */
/* texture store bookkeeping for PS2_TEX_STATS: [0] GS decodes, [1] native; bytes are decoded RGBA */
static u64 texst_hit[2], texst_new[2], texst_spare[2], texst_lru[2], texst_lost[2], texst_new_bytes[2],
           texst_reuse_bytes[2];
static int texst_every = -1;            /* PS2_TEX_STATS interval in fields (0 = off) */
static int texst_enabled(void) {
    if (texst_every < 0) {
        const char *e = getenv("PS2_TEX_STATS");
        texst_every = e && *e && *e != '0' ? atoi(e) : 0;
        if (texst_every == 1) texst_every = 600;
    }
    return texst_every > 0;
}
/* which textures make the store's traffic (new slots, updates, take-overs), per stats interval: GS decodes by base
   address, format and size, native ones by size */
#define TEXST_CENS_N 256u
static struct { u64 key; u32 w, h, n_new, n_upd, n_lru; u64 bytes; } texst_cens[TEXST_CENS_N];
static u32 texst_tag;                   /* native: 1 = a region of a GS decode, 2 = from the upload records */
static void texst_census(u64 key, u32 w, u32 h, int what, size_t bytes) {
    u64 k = (key >> 63) ? (1ull << 63) | texst_tag : key;
    u32 i = (u32)(((k ^ ((u64)w << 20) ^ h) * 0x9E3779B97F4A7C15ull) >> 56), n;
    for (n = 0; n < TEXST_CENS_N; n++, i = (i + 1u) % TEXST_CENS_N) {
        if (texst_cens[i].bytes && (texst_cens[i].key != k || texst_cens[i].w != w || texst_cens[i].h != h)) continue;
        texst_cens[i].key = k; texst_cens[i].w = w; texst_cens[i].h = h;
        if (what == 0) texst_cens[i].n_new++; else if (what == 1) texst_cens[i].n_upd++; else texst_cens[i].n_lru++;
        texst_cens[i].bytes += bytes;
        return;
    }
}

