enum { VS_FENCE, VS_ACQUIRE, VS_RECORD, VS_SUBMIT, VS_PRESENT, VS_TOTAL, VS_N };
static struct {
    u64 start, n, ns[VS_N], peak[VS_N], slow, failed;
    u64 draws, uploads, selfreads, pipe_ns, pipes;
} render_speed;
static u64 speed_xr_wait_ns, speed_xr_wait_peak;   /* time in ps2_xr_frame_begin (xrWaitFrame), inside record */
static void renderer_speed_sample(const u64 *ns, int submitted) {
    u64 now = vk_mono_ns();
    if (!render_speed.start) render_speed.start = now;
    render_speed.n++;
    render_speed.failed += !submitted;
    render_speed.slow += ns[VS_TOTAL] > 16683333ull;
    for (int i = 0; i < VS_N; i++) {
        render_speed.ns[i] += ns[i];
        if (ns[i] > render_speed.peak[i]) render_speed.peak[i] = ns[i];
    }
    if (now - render_speed.start < 5000000000ull) return;
    double n = (double)render_speed.n;
    ps2_log("vk-speed: dt=%.2fs attempts=%llu skipped=%llu host_over_16.68ms=%llu "
            "host_ms avg=%.3f max=%.3f draws/attempt=%.1f uploads=%llu selfread_draws=%llu",
        (now-render_speed.start)/1e9, (unsigned long long)render_speed.n,
        (unsigned long long)render_speed.failed, (unsigned long long)render_speed.slow,
        render_speed.ns[VS_TOTAL]/1e6/n, render_speed.peak[VS_TOTAL]/1e6,
        (stat_draws-render_speed.draws)/n,
        (unsigned long long)(stat_texuploads-render_speed.uploads),
        (unsigned long long)(stat_selfreads-render_speed.selfreads));
    ps2_log("vk-speed: host_ms avg/max fence=%.3f/%.3f acquire=%.3f/%.3f "
            "record=%.3f/%.3f submit=%.3f/%.3f present=%.3f/%.3f "
            "new_pipelines=%llu compile_total_ms=%.3f (included in record; not GPU time)",
        render_speed.ns[VS_FENCE]/1e6/n, render_speed.peak[VS_FENCE]/1e6,
        render_speed.ns[VS_ACQUIRE]/1e6/n, render_speed.peak[VS_ACQUIRE]/1e6,
        render_speed.ns[VS_RECORD]/1e6/n, render_speed.peak[VS_RECORD]/1e6,
        render_speed.ns[VS_SUBMIT]/1e6/n, render_speed.peak[VS_SUBMIT]/1e6,
        render_speed.ns[VS_PRESENT]/1e6/n, render_speed.peak[VS_PRESENT]/1e6,
        (unsigned long long)(speed_pipe_n-render_speed.pipes),
        (speed_pipe_ns-render_speed.pipe_ns)/1e6);
    ps2_log("vk-speed: xr_wait avg/max %.3f/%.3f ms (part of record)", speed_xr_wait_ns / 1e6 / n, speed_xr_wait_peak / 1e6);
    ps2_log("vk-count per frame: draws %.0f pipelines %.0f descsets %.0f push %.0f scissors %.0f target-switches %.0f "
            "begin-rendering %.0f barrier-calls %.0f barrier-images %.0f snapshots %.1f (+%.1f reused for DATE, %.1f skipped, "
            "%.2f Mpx copied for DATE regions) colclip %.1f fast-clears %.1f dynamic-blend-sets %.0f "
            "date-alpha-meshes %.1f (%.1f planar ones read in place; kept: %.1f not a small triangle list, %.1f "
            "screen-space in-between path, %.1f eye near the plane, %.1f not planar, %.1f overlapping, %.1f degenerate, "
            "%.1f sliver)",
            rl_stat.draw / n, rl_stat.pipe / n, rl_stat.desc / n, rl_stat.push / n, rl_stat.scis / n, rl_stat.sel / n,
            rl_stat.begin / n, rl_stat.barc / n, rl_stat.bari / n, rl_stat.snap / n, snap_alpha_hits / n,
            snap_region_skips / n, snap_region_px / n / 1e6, rl_stat.clip / n, stat_fast_clears / n, rl_stat.dynb / n,
            rl_stat.dawm / n, rl_stat.dawq / n, dq_why[0] / n, dq_why[1] / n, dq_why[2] / n, dq_why[4] / n,
            dq_why[5] / n, dq_why[6] / n, dq_why[7] / n);
    {   extern u64 vbs_sum, vbs_max, vbs_n;    /* (fq_opt: the GS vertices a recorded frame uploads) */
        if (vbs_n) ps2_log("vk-vb per frame: GS vertices mean %.0f max %llu (%.0f KB mean, %llu frames)", (double)vbs_sum / (double)vbs_n,
                           (unsigned long long)vbs_max, (double)vbs_sum * (double)sizeof(ps2_vk_vertex) / 1024.0 / (double)vbs_n,
                           (unsigned long long)vbs_n);
        vbs_sum = vbs_max = vbs_n = 0;
    }
    ps2_log("vk-date per frame: local-read draws %.1f (native %.1f, GS %.1f) feedback barriers %.1f (+%.1f skipped by "
            "lrbar) DATE snapshot-path draws %.1f",
            (dtc_lrd_n + dtc_lrd_g) / n, dtc_lrd_n / n, dtc_lrd_g / n, dtc_lrb / n, dtc_lrb_skip / n, dtc_snapd / n);
    dtc_lrb = dtc_lrb_skip = dtc_lrd_n = dtc_lrd_g = dtc_snapd = 0;
    dbt_count_log(n);                     /* (PS2_DATE_BATCH: runs, box skips; PS2_DATE_LOCAL_HF) */
    p4p_count_log(n);                     /* (perf4_passes: dynamic state, upload batches, cockpit fold, cloud queue) */
    memset(dq_why, 0, sizeof dq_why);
    stat_fast_clears = 0;
    snap_alpha_hits = snap_region_skips = snap_region_px = 0;
    memset(&rl_stat, 0, sizeof rl_stat);
    speed_xr_wait_ns = speed_xr_wait_peak = 0;
    memset(&render_speed, 0, sizeof(render_speed));
    render_speed.start = now;
    render_speed.draws = stat_draws; render_speed.uploads = stat_texuploads;
    render_speed.selfreads = stat_selfreads;
    render_speed.pipe_ns = speed_pipe_ns; render_speed.pipes = speed_pipe_n;
}

