/* coarse shading (VK_KHR_fragment_shading_rate) for the cloud impostor sprites: their cost is fill, shading once per
   2x2 pixels keeps blending, depth and coverage per pixel. PS2_VRS=0 turns it off. */
static int vrs_ok;
/* Foveated shading (PS2_VRS_FOV; the rate images and their use: vrs_* after cl_point). Every eye layer of the render
   target is the whole symmetric image; the headset shows only the crop of it that covers that eye's own frustum (Quest
   3: L x 0..0.81 of the width, R x 0.19..1, both y 0.16..1: a third of each layer is drawn and never shown). A
   VK_KHR_fragment_shading_rate attachment per eye layer shades that part once per 4x4 pixels ("crop"), and with
   "zones" also the world draws (class 1) in rings around each eye's optical axis: 1x1 inside PS2_VRS_FOV_ZONES r1,
   2x1 / 1x2 (coarse along the radius, where the planar image has the most pixels per degree) to r2, 2x2 to r3, 4x4
   beyond. Coverage, depth and blending stay per pixel; HUD, text, target boxes, the cockpit model and its screens stay
   1x1 (their pipelines keep the combiner KEEP, or their pass has the crop image: 1x1 wherever the headset looks).
   With the attachment on the device every pipeline made here carries the attachment flag (vrs_create_gp); GS and mesh
   pipelines that take the attachment's rate are key bit 52 (pipe_fov_req). */
static int vrs_fov_mode;            /* 0 off (as before), 1 crop, 2 zones: decided at device creation */
static int vrs_att_ok;              /* the attachment rate is enabled on the device */
static int vrs_att_nontrivial;      /* the MAX combiner: cloud sprites keep their own 2x2 or the attachment's, coarser */
static int vrs_att_layered;         /* layeredShadingRateAttachments: one attachment layer per multiview eye */
static int vrs_att_zwrite;          /* fragmentShadingRateWithShaderDepthStencilWrites */
static u32 vrs_att_tw = 16u, vrs_att_th = 16u;   /* attachment texel size (pixels) */
static u8 vrs_rate_best[3][3];      /* [log2 w][log2 h]: the largest supported rate not larger in either axis (code) */
static int pipe_fov_req;            /* get_pipeline_ex: the pipeline asked for takes the attachment's rate */
/* ACZ_VR_COCKPIT_VRS (perf4_cockpit 2026-11-03; opt-in, default 0 = as before): the 3D cockpit's multisampled pass shades
   parts of the model coarser away from each eye's optical axis, the cockpit's counterpart of PS2_VRS_FOV=zones (the
   cockpit pass is fragment-bound: with a 1-pixel scissor 0.00-0.21 ms of its 0.5-2.2 ms are left). A bit mask: 1 =
   the solid parts without cut-out texels (their colour pass after the depth pre-pass), 2 = the glass, 3 = both; the
   cut-out parts (their alpha test), the HUD screens, the depth, the coverage and the edges stay per pixel / sample.
   Measured (exclusive 4x in-run A/B, M4 / M1 with the canopy wet; MiG-31, Rafale M, F-117A): the glass bit saves
   0.14-0.21 / 0.24-0.37 ms of its 0.37-0.48 / 0.67-0.87, the solid bit 0.02-0.05 of the model's 0.48-1.06 (the dense
   models are bound by their small triangles, whose coarse quads are as many invocations as fine ones) while it
   smears panel text off-axis: bit 2 is the one for a headset look. ACZ_VR_COCKPIT_VRS_ZONES=
   r1,r2 (degrees off the eye's axis, default 30,40): 1x1 inside r1, 2x1 / 1x2 to r2 (coarse along the radius, where the
   planar image has the most pixels per degree), 2x2 beyond (at 4 samples the device's largest coarse fragment). Done by
   the primitive's shading rate (cockpit_vrs.vert at the provoking vertex: per triangle, the cockpit's 5 cm AO
   subdivision keeps them small) combined by MAX with the pass's crop image, so no other pipeline of the pass changes;
   needs the device's primitiveFragmentShadingRate (enabled only when asked for). Measurement: ACZ_VR_COCKPIT_AB items
   cvrs (1) / cvrsg (2) / cvrsa (3) against the configured value; PS2_PERF_AB_FLIP=cvrs: the re-draw of a dumped frame
   the other way (configured 0: zones on both; else off). Not a default: the image changes off-axis (texture detail,
   lighting, the glass's scratches, dust and drops in 2x2 blocks) -- a headset decision. */
static struct { int init, mode, want, want_solid, want_wet; float r[2]; } cvrs;
static int cq_zones_wanted(int wet);  /* (ACZ_VR_CANOPY_QUALITY: a rung's zones, cq_*: wet = also on a wet glass) */
static void cq_rings(float *r);       /* (... the configured rung's rings) */
static int vrs_prim_ok;             /* the device's primitive shading rate is enabled (cvrs) */
/* ACZ_VR_COCKPIT_VRS_DRY (perf5_glasszones 2026-11-03; the user agreed to shading zones on the dry canopy only): the
   glass's shading zones (ACZ_VR_COCKPIT_VRS bit 2, its rings ACZ_VR_COCKPIT_VRS_ZONES) only while nothing on the glass
   would show them, full rate otherwise. The gate shuts in the same frame as any of: water or frozen drops, mist, the
   condensation film, frost / rime (canopy_active()'s tests and thresholds -- below them cockpit.frag draws none of it),
   a crack or a debris chip (fx_cracks), a debris fleck, or the sun lighting the glass's wear 10-85 deg off the view's axis
   (ACZ_VR_COCKPIT_VRS_DRY_SUN: the halo of lit scratches and dust specks lies within ~20 deg of the sun's image, so it
   reaches the coarse ring from 30 deg; the sun from gfx_frame, a frame late, as it lights the wear: the moon at night
   too, less in a cloud's shadow or in cloud); it opens after ACZ_VR_COCKPIT_VRS_DRY_HOLD seconds (2) with none of them: a
   canopy or a head hovering at a threshold cannot make the rate flicker, and both switches happen where nothing visible
   changes (the drops' inputs and the gate come from the same canopy_update). Soot / dust, grime / smear and a kill's
   grit pits do not shut it (their crops stay at the dry glass's level, below). The glass's own wear away from the sun (scratches, dust,
   glare, the interior's reflection, the sun's glint) is "dry". Both pipelines exist from the cockpit's load (cvrs_mk,
   the solid parts' twins only when bit 1 can be asked for; with PS2_PERF_GLASS_VARIANTS each variant's zone twin, gxvz,
   so a dry glass takes both the zones and its specialised shader -- the gate's open states are the variants' dry,
   soot and grime cases), so the switch costs nothing in a frame. Off by default
   (ACZ_VR_COCKPIT_VRS_DRY=1 asks for it; 0: no primitive shading rate, no twins, main's frame as it was): the numbers
   stay in perf4_cockpit's dry bound, but side by side in 4x crops the glass's smallest features beyond 30 deg are
   softer -- dust specks 2x2 blobs instead of crisp dots, a 1-px scratch bit fainter or gone. A headset decision. Never
   in the recordings' cinematic view (cine_t: not centred on an eye). Logged: the gate's switches with the reason (the first 8, then every 64th; all with
   ACZ_DEBUG_VRS_DRY=s) and every 5 minutes (or s) its share of the frames and why it was shut. Measurement:
   ACZ_VR_COCKPIT_AB item cvrsd (the gate in its blocks, whatever the switch), PS2_PERF_AB_FLIP=cvrsdry (the re-draw of
   a dumped frame with the gate the other way); ACZ_VR_CANOPY_TEST_SEQ (canopy states in one run). */
#define CVD_DEFAULT 0                        /* (opt-in: the user's look in the headset decides; see below) */
enum { CVD_WATER = 1, CVD_MIST = 2, CVD_FILM = 4, CVD_ICE = 8, CVD_GRIME = 16, CVD_SOOT = 32, CVD_CRACKS = 64,
       CVD_FLECKS = 128, CVD_SUN = 256, CVD_CHIPS = 512, CVD_GRIT = 1024, CVD_HOLD = 2048 };
/* what shuts the gate: the states whose 4x same-frame crops (exclusive, Rafale M over M4's sea; zones vs none, the left
   eye's crop, % of the pixels > 8 levels; a private script ev/S_zones_23) showed the zones -- the drops
   0.30-0.41 % and the last drops (water 0.03) 0.023-0.029 %, frozen drops + rime 0.26-0.33 %, cracks 0.20 %, a fleck
   0.0077 % (its edge blocky), the film's diffused world in 2x2 blocks (> 2 levels on 0.33 % of the crop), the sun's lit
   wear 38-41 deg off the axis 0.043-0.050 %; not the soot film 0.45 (0.0006-0.0019 %) or grime 0.5 + smear 0.3
   (0.0005-0.0022 %), as the dry glass (0.0007-0.0031 %: single dust specks 2x2 instead of 1-2 px), nor a kill's grit
   pits (0.15-0.4 mm, their fine scratches; ps2_crk_grit) 38-44 deg off the axis (0.0001-0.0008 %, ev/X_chips3_23).
   Debris chips from bits and chunks (pits up to 3.5 mm with micro-crack stars) stay with the cracks: the same crack
   layer's lines, not measured on their own. (ACZ_VR_SMOOTH_LAYER_COCKPIT=1 reuses a dry canopy's game-frame
   cockpit in the in-between frames: the zones' saving then counts in the game frames only.) */
#define CVD_GATE (CVD_WATER | CVD_MIST | CVD_FILM | CVD_ICE | CVD_CRACKS | CVD_FLECKS | CVD_SUN | CVD_CHIPS)
static struct {
    int init, on, dbg; float hold, log_s;   /* ACZ_VR_COCKPIT_VRS_DRY, _HOLD (s); ACZ_DEBUG_VRS_DRY (s: every switch) */
    float sun_lo, sun_hi;                   /* ACZ_VR_COCKPIT_VRS_DRY_SUN (deg off the view's axis) */
    float sun[4];                           /* the glass wear's sun (cockpit frame) and its light (gfx_frame; 0: none) */
    int dry, why, last_why;                 /* the gate this frame; what kept it at full rate (CVD_*) */
    u64 wet_ns;                             /* the last time anything was on the glass (0: never) */
    u64 nz, nf, nsw, nwhy[12], log_ns;      /* frames zoned / at full rate, switches, full-rate frames per reason */
} cvd;
static void cvd_cfg(void) {
    if (cvd.init) return;
    cvd.init = 1;
    const char *e = getenv("ACZ_VR_COCKPIT_VRS_DRY"), *x = getenv("PS2_XR"), *m = getenv("PS2_XR_MODE");
    int xr = x && *x == '1' && m && !strncmp(m, "stereo", 6);
    cvd.on = e && *e ? atoi(e) != 0 : CVD_DEFAULT && xr;
    cvd.hold = 2.0f;
    e = getenv("ACZ_VR_COCKPIT_VRS_DRY_HOLD");
    if (e && *e) cvd.hold = (float)atof(e);
    if (!(cvd.hold >= 0.0f && cvd.hold <= 600.0f)) cvd.hold = 2.0f;
    cvd.sun_lo = 10.0f; cvd.sun_hi = 85.0f;
    e = getenv("ACZ_VR_COCKPIT_VRS_DRY_SUN");
    if (e && *e) sscanf(e, "%f,%f", &cvd.sun_lo, &cvd.sun_hi);
    if (!(cvd.sun_lo >= 0.0f && cvd.sun_lo <= 180.0f)) cvd.sun_lo = 10.0f;
    if (!(cvd.sun_hi >= cvd.sun_lo && cvd.sun_hi <= 180.0f)) cvd.sun_hi = cvd.sun_lo;
    e = getenv("ACZ_DEBUG_VRS_DRY");
    cvd.dbg = e && *e;
    cvd.log_s = cvd.dbg ? (float)atof(e) : 300.0f;
    if (!(cvd.log_s >= 1.0f)) cvd.log_s = 300.0f;
}
static int cvrs_tok(const char *list, const char *name) {     /* name is an item of the comma list */
    size_t n = strlen(name);
    for (const char *p = list; (p = strstr(p, name)) != NULL; p += n)
        if ((p == list || p[-1] == ',') && (p[n] == 0 || p[n] == ',')) return 1;
    return 0;
}
static void cvrs_cfg(void) {
    if (cvrs.init) return;
    cvrs.init = 1;
    cvd_cfg();
    const char *e = getenv("ACZ_VR_COCKPIT_VRS");
    cvrs.mode = !e || !*e ? 0 : !strcmp(e, "solid") ? 1 : !strcmp(e, "glass") ? 2 : !strcmp(e, "all") ? 3 : atoi(e);
    if (cvrs.mode < 0 || cvrs.mode > 3) cvrs.mode = 0;
    cvrs.r[0] = 30.0f; cvrs.r[1] = 40.0f;
    cq_rings(cvrs.r);
    e = getenv("ACZ_VR_COCKPIT_VRS_ZONES");
    if (e) sscanf(e, "%f,%f", &cvrs.r[0], &cvrs.r[1]);
    if (!(cvrs.r[0] >= 0.0f)) cvrs.r[0] = 0.0f;
    if (cvrs.r[0] > 89.0f) cvrs.r[0] = 89.0f;
    if (!(cvrs.r[1] >= cvrs.r[0])) cvrs.r[1] = cvrs.r[0];
    if (cvrs.r[1] > 89.0f) cvrs.r[1] = 89.0f;
    const char *ab = getenv("ACZ_VR_COCKPIT_AB"), *w = getenv("ACZ_VR_COCKPIT_AB_WHAT"), *f = getenv("PS2_PERF_AB_FLIP");
    cvrs.want = cvrs.mode > 0 || (ab && atoi(ab) > 0 && w && strstr(w, "cvrs")) || (f && strstr(f, "cvrs")) || cvd.on
                || cq_zones_wanted(0);
    /* the solid parts' twins only when something can ask for bit 1 (ACZ_VR_COCKPIT_VRS_DRY alone needs the glass's) */
    cvrs.want_solid = (cvrs.mode & 1) || (ab && atoi(ab) > 0 && w && (cvrs_tok(w, "cvrs") || cvrs_tok(w, "cvrsa")))
                      || (f && cvrs_tok(f, "cvrs"));
    /* the zones on a wet glass too: the zone twins of the wet glass variants (gxv_mk); the gate alone never asks for them */
    cvrs.want_wet = (cvrs.mode & 2) || (ab && atoi(ab) > 0 && w && (cvrs_tok(w, "cvrsg") || cvrs_tok(w, "cvrsa")))
                    || (f && cvrs_tok(f, "cvrs")) || cq_zones_wanted(1);
}
static VkResult vrs_create_gp(VkDevice d, VkPipelineCache c, uint32_t n, const VkGraphicsPipelineCreateInfo *ci,
                              const VkAllocationCallbacks *a, VkPipeline *p) {
    if (!vrs_att_ok || n > 8u) return (vkCreateGraphicsPipelines)(d, c, n, ci, a, p);
    VkGraphicsPipelineCreateInfo cp[8];
    for (uint32_t i = 0; i < n; i++) {
        cp[i] = ci[i];
        cp[i].flags |= VK_PIPELINE_CREATE_RENDERING_FRAGMENT_SHADING_RATE_ATTACHMENT_BIT_KHR;
    }
    return (vkCreateGraphicsPipelines)(d, c, n, cp, a, p);
}
/* every graphics pipeline of this file: it may be bound inside a rendering that has the attachment */
#define vkCreateGraphicsPipelines(d, c, n, ci, a, p) vrs_create_gp((d), (c), (n), (ci), (a), (p))
/* a pipeline that takes the attachment's rate (combiner REPLACE), chained in front of next; next itself when off */
static const void *vrs_fsr_replace(VkPipelineFragmentShadingRateStateCreateInfoKHR *s, const void *next) {
    if (!vrs_att_ok) return next;
    memset(s, 0, sizeof *s);
    s->sType = VK_STRUCTURE_TYPE_PIPELINE_FRAGMENT_SHADING_RATE_STATE_CREATE_INFO_KHR;
    s->pNext = next;
    s->fragmentSize.width = 1u; s->fragmentSize.height = 1u;
    s->combinerOps[0] = VK_FRAGMENT_SHADING_RATE_COMBINER_OP_KEEP_KHR;
    s->combinerOps[1] = VK_FRAGMENT_SHADING_RATE_COMBINER_OP_REPLACE_KHR;
    return s;
}

#define SPLIT_EARLY 3u            /* PS2_PERF_EARLY_SUBMIT: at most this many early submissions a frame */
#define SPLIT_MAX 4u              /* ... + one: the headset's part ahead of the recording's view (ACZ_REC_CINE_AFTER) */
typedef struct {
    VkCommandBuffer cmd;           /* the buffer being recorded (cmd0, or one of xcmd after an early submission) */
    VkCommandBuffer cmd0, xcmd[SPLIT_MAX];
    VkCommandPool pool;            /* PS2_PERF_FRAME_POOLS: cmd0 and xcmd's own pool, reset whole at the frame's start */
    u32 nsplit, ev_nsplit;         /* early submissions while recording / in the frame being timed */
    VkCommandBuffer ccmd;          /* PS2_PERF_CLOUD_ASYNC: the far cloud update for the second queue */
    int cla;                       /* ... this recording: 0 none, 1 ccmd recorded, 2 submitted, 3 a part waits for it */
    int cla_here;                  /* ... the part being recorded must wait for it (a reader of the far map is in it) */
    u64 cla_v1, cla_v2;            /* ... timeline: the part before it done, it done */
    u64 cla_done;                  /* ... the value its last submission signals (the host waits before reusing ccmd) */
    int prefilled;                 /* PS2_PERF_PREFILL: the frame's vertices and meshes were copied before xrWaitFrame */
    int preuploaded;               /* PS2_PERF_PREUPLOAD: its texture uploads were recorded before xrWaitFrame */
    u64 ev_t0_ns, ev_sub1_ns;      /* host: recording start (after xrWaitFrame), first submission (frame latency) */
    int rx_slot1;                  /* ACZ_REC_EXACT: host buffer + 1 of this frame's window capture (0 none) */
    u64 rx_tag, rx_tpub;           /* ... the field it shows (real-time count) and that list's publication time */
    VkSemaphore acquired, rendered;
    VkFence fence;
    VkQueryPool timing_queries;
    int timing_pending;
    int timing_stereo;             /* the frame wrote the per-pass timestamps 3 and 4 */
    int timing_kind;               /* 0 other, 1 synchronous frame drawn once, 2 drawn per eye */
    VkQueryPool class_queries;     /* PS2_GPU_CLASSES=1: a timestamp at each change of draw class (multiview: two
                                      query slots a stamp, gpu_stamp_slot) */
    u32 class_n;
    u16 *class_cat;                /* class << 5 | target slot of the segment starting at each timestamp; 0xFFFF end */
    int draw_mode;                 /* PS2_GPU_DRAWS=1: this frame has a timestamp before every draw */
    /* what the frame's commands did (PS2_GPU_TRACE / PS2_GPU_SPIKE / the governor): texture uploads, their KB, the
       mipmapped ones, render targets made, new pipelines, an in-between frame, the GS field, the governor level */
    u32 ev_up, ev_upkb, ev_upmip, ev_tgt, ev_pipe, ev_rr, ev_field, ev_gov;
    u32 ev_p2;                     /* PS2_PERF_RECORD_EARLY: the frame's scene was recorded and submitted before the wait */
    u64 ev_frame;
    double ev_lat_ms, ev_wall_ms;  /* (filled at collection) frame latency estimate, GPU wall time incl. part gaps */
    double ev_t_unix;              /* PS2_GPU_TRACE: wall clock (s since 1970) at the end of the frame's recording */
    u32 ev_boost;                  /* PS2_PERF_GPU_BOOST mode in effect for the frame */
    u32 ev_cine, cine_xr_part;     /* ACZ_REC_CINE: 1 the frame drew the view (2: its A/B arm without ACZ_REC_CINE_AFTER);
                                      the early-submitted part (1-based) whose end released the headset's images, 0 none */
    VkBuffer vbuf;
    VkDeviceMemory vmem;
    void *vptr;
    VkBuffer sbuf;
    VkDeviceMemory smem;
    void *sptr;
    size_t soff;
    VkBuffer dsbuf;                /* PS2_PERF_DEVICE_BUFFERS bit 2: device-local staging, used first (staging_take) */
    VkDeviceMemory dsmem;
    void *dsptr;
    size_t dsoff;
    VkBuffer ovbuf;
    VkDeviceMemory ovmem;
    void *ovptr;
    VkBuffer mvbuf, mibuf, mcbuf;
    VkDeviceMemory mvmem, mimem, mcmem;
    void *mvptr, *miptr, *mcptr;
    VkDescriptorSet mset;
    VkBuffer mlv_vbuf, mlv_ibuf;   /* the mirrors' live map: its batches' vertices and indices (mlv_pass) */
    VkDeviceMemory mlv_vmem, mlv_imem;
    void *mlv_vptr, *mlv_iptr;
} vk_frame;

/* ---- The rear-view mirrors' mode (agent perf6_mirrors 2026-11-04; the user: "the mirrors can be switched off by
   default; put light stand-ins that reflect the tonality ... they are useless and don't look good").
   ACZ_VR_COCKPIT_MIRRORS (the ENHANCEMENTS row COCKPIT > REAR-VIEW MIRRORS), read once:
   - unset, "" or "tone": TONE, the default since 2026-11-04 -- the glass carries the scene's tonality (cockpit.frag
     mir_tone: the game's sky colours by the reflected direction with a soft horizon, a soft glow where the sun is
     behind, the cloud's grey inside one, the tunnel's gloom, the glass's Fresnel and tint) and nothing else: no live
     map (mlv_*), no real view (mirv_*), no cubes baked at load (mir_cube_init), no aim clearance's ray casts
     (mirocc_*), no mirror terrain atlas (zero_terrain.c), so none of their GPU, worker, renderer, VRAM or load work;
   - "live" or a strength > 0 (up to 2): LIVE, the default before (everything above, as before);
   - "sky": SKY (no live map, as before);
   - "0" or anything else: OFF (the glass as the model paints it: the flat grey of before). */
enum { MIR_OFF, MIR_TONE, MIR_SKY, MIR_LIVE };
static int mir_mode(void) {
    static int md = -1;
    if (md < 0) {
        const char *m = getenv("ACZ_VR_COCKPIT_MIRRORS");
        md = !m || !*m || !strcmp(m, "tone") ? MIR_TONE : !strcmp(m, "sky") ? MIR_SKY
           : !strcmp(m, "live") || atof(m) > 0.0 ? MIR_LIVE : MIR_OFF;
    }
    return md;
}

/* ---- The rear-view mirrors' live map (agent mir_live 2026-10-29; the user 2026-10-28 22:19 / 23:15: "I don't see
   those aircraft in the mirror", "not a single aircraft ... not a real mirror"; 2026-10-29: "they must not load the
   system much"). Step M2 of docs/research/2026-10-24/mirrors-lookback.md: the other aircraft the game draws every frame
   (rn_vp_model.c mlv_batch: their batches behind the camera are converted anyway) are drawn once per game frame, mono,
   by an aircraft-fixed rear camera into a small map (mlv_pass) with the game's own pipelines, textures, light rows and
   fog; cockpit.frag's mirror glass looks it up by each eye's reflected ray (at infinity, as the sky), over stage 1's
   sky, clouds and haze, under the cockpit cube. Frames between game frames reuse the map. No work while the feature is
   off, the model has no mirrors, the view is not the cockpit, or no mirror (with a 15 deg margin) was in view in the
   last second (mlv_cockpit's box test; the flag goes to the worker through mlv_pub). Switches (read once):
   ACZ_VR_COCKPIT_MIRRORS_LIVE (on; 0 = stage 1 only), _LIVE_RES (the map's width, 1024), _LIVE_RANGE (m, 4000),
   _LIVE_MAXBATCH (256), _LIVE_MARGIN (deg, 12: the rear frustum around the mirrors' reflected cones, for the head),
   _LIVE_AB (s: off every other period, the in-run A/B); ACZ_DEBUG_COCKPIT_MIRRORS_LIVE=N (log every N-th map),
   ACZ_DEBUG_COCKPIT_MIRRORS_LIVE_ID=1/2 (the identity test: the map drawn with the head camera at the frame's size --
   1 through the rear camera's maths, 2 the rows as they come -- and dumped with the eye dumps, beside the frame before
   the cockpit). PS2_PERF_AB_FLIP=mirlive: the A/B re-draw without the map. The aim (ACZ_VR_COCKPIT_MIRRORS_AIM, _AIM_AZ)
   is mir_check's. */
static struct {
    int init, on, res, maxb, dbg, id, ab;
    float range_m, margin, aim, aim_az, ground_m, clear;
    int gmax, clouds, sharp, turn;
} mlvc;
static void mlv_cfg_init(void) {
    if (mlvc.init) return;
    mlvc.init = 1;
    const char *e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE");
    int md = mir_mode();                         /* (perf6_mirrors: none with TONE or OFF; SKY / LIVE as before) */
    mlvc.on = md >= MIR_SKY && (e && *e ? atoi(e) != 0 : md == MIR_LIVE);
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_RES"); mlvc.res = e && *e ? atoi(e) : 1024;
    if (mlvc.res < 128) mlvc.res = 128;
    if (mlvc.res > 2048) mlvc.res = 2048;
    mlvc.res &= ~7;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_RANGE"); mlvc.range_m = e && *e ? (float)atof(e) : 4000.0f;
    if (!(mlvc.range_m >= 100.0f)) mlvc.range_m = 100.0f;
    if (mlvc.range_m > 20000.0f) mlvc.range_m = 20000.0f;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_MAXBATCH"); mlvc.maxb = e && *e ? atoi(e) : 600;
    if (mlvc.maxb < 1) mlvc.maxb = 1;
    if (mlvc.maxb > 4096) mlvc.maxb = 4096;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_GROUND"); mlvc.ground_m = e && *e ? (float)atof(e) : 0.0f;
    if (!(mlvc.ground_m >= 0.0f)) mlvc.ground_m = 0.0f;
    if (mlvc.ground_m > mlvc.range_m) mlvc.ground_m = mlvc.range_m;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_GROUND_MAX"); mlvc.gmax = e && *e ? atoi(e) : 40;
    if (mlvc.gmax < 0) mlvc.gmax = 0;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_MARGIN"); mlvc.margin = e && *e ? (float)atof(e) : 12.0f;
    if (!(mlvc.margin >= 0.0f)) mlvc.margin = 0.0f;
    if (mlvc.margin > 40.0f) mlvc.margin = 40.0f;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_AB"); mlvc.ab = e ? atoi(e) : 0;
    if (mlvc.ab < 0) mlvc.ab = 0;
    e = getenv("ACZ_DEBUG_COCKPIT_MIRRORS_LIVE"); mlvc.dbg = e ? atoi(e) : 0;
    e = getenv("ACZ_DEBUG_COCKPIT_MIRRORS_LIVE_ID"); mlvc.id = e ? atoi(e) : 0;
    if (mlvc.id < 0 || mlvc.id > 2) mlvc.id = 0;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_AIM");
    mlvc.aim = e && *e && strcmp(e, "off") ? (float)atof(e) : (e && *e ? 0.0f : 3.0f);
    if (mlvc.aim > 30.0f) mlvc.aim = 30.0f;
    if (mlvc.aim < -30.0f) mlvc.aim = -30.0f;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_CLOUDS"); mlvc.clouds = !(e && *e == '0');   /* (phase 4: cockpit.frag) */
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_SHARP"); mlvc.sharp = !(e && *e == '0');     /* (phase 4: mlv_look) */
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_LIVE_TURN"); mlvc.turn = !(e && *e == '0');       /* (mir_sharp: mlv_cockpit) */
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_AIM_CLEAR");                 /* (bug #205: mir_aim_clear) */
    mlvc.clear = e && *e ? (strcmp(e, "off") ? (float)atof(e) : 1.0f) : 0.5f;
    if (!(mlvc.clear > 0.0f) || mlvc.clear > 1.0f) mlvc.clear = 1.0f;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_AIM_AZ");
    mlvc.aim_az = e && *e && strcmp(e, "off") ? (float)atof(e) : 0.0f;
    if (mlvc.aim_az > 90.0f) mlvc.aim_az = 90.0f;
    if (mlvc.aim_az < -90.0f) mlvc.aim_az = -90.0f;
    if (mlvc.on)
        ps2_log("vk: cockpit mirrors' live map on (map %d wide, range %.0f m, at most %d batches, margin %.0f deg, ground objects %.0f m%s; "
                "ACZ_VR_COCKPIT_MIRRORS_LIVE=0 turns it off)", mlvc.res, (double)mlvc.range_m, mlvc.maxb,
                (double)mlvc.margin, (double)mlvc.ground_m, mlvc.id ? "; IDENTITY TEST" : "");
}
/* ---- The rear-view mirrors' real view (agent mir_sharp 2026-10-29, bug #230; the user 19:43:50 "what I see behind in
   the mirror is pixelated", 22:24:20 "the upper mirror, there is something pixelated, a pixel mush. This definitely needs
   fixing", 22:52:42 "the mirrors still need fixing"). What lay behind the pilot in the mirrors -- the headrest, the
   canopy's frame and rails, the spine and fins -- came from a cube of the model seen from each glass, marched along the
   reflected ray in 9 steps (cockpit.frag mir_interior): the F-15C's top mirror at its +3 deg aim looks over the headrest
   along the canopy's rails (47 % of its rays meet a part), and the march drew them as terraced, stair-stepped streaks a
   few eye pixels wide that differ in each eye and change with every millimetre the head moves: the "pixel mush". Now
   the parts are drawn for real, every frame, each eye, each mirror: a planar mirror's image is the scene seen from the
   eye's mirror image E' = E - 2 ((E - c) . n) n through the glass, so cockpit.vert draws the model with the head at E',
   its rows (x, y, -n) -- the glass's own axes, a camera looking through the glass along n -- and a projection that
   puts the glass's extent (u0..u1, v0..v1 in the plane) onto the mirror's slot of an atlas (k texels a metre: x = k (u -
   u0), y = k (v1 - v) whatever the eye, so the glass reads the atlas by its own point, cockpit.frag mirv_look), the near
   plane at the glass (reversed depth near / w: what lies behind the mirror is clipped). Lit as the cockpit is lit (the
   game's lights, the scene light, the sun's shadow map, flashes: the same push as the solid parts), 4x multisampled and
   resolved, so the parts' edges are as clean as the cockpit's own; the far scene (sky, our clouds, the live map's
   terrain and aircraft) shows where no part is (alpha = coverage). Mirrors out of view (+-15 deg) cost nothing.
   ACZ_VR_COCKPIT_MIRRORS_REAL (on; 0 = the cube march as before), _REAL_DENSITY (the atlas's texels per eye pixel at
   the design eye, 1.25), _REAL_MSAA (4; 1 = none), _REAL_AB (s, test: the cube march every other period, for the GPU
   A/B), ACZ_DEBUG_COCKPIT_MIRRORS_REAL=N (log every N-th view: parts, triangles, slots); PS2_PERF_AB_FLIP=mirreal (the
   same-frame image A/B: the re-draw with the cube march). */
static struct { int init, on, msaa, ab, dbg; float dens; } mirvc;
static void mirv_cfg_init(void) {
    if (mirvc.init) return;
    mirvc.init = 1;
    const char *e = getenv("ACZ_VR_COCKPIT_MIRRORS_REAL");
    mirvc.on = !(e && *e == '0') && mir_mode() != MIR_TONE;   /* (perf6_mirrors: TONE draws no parts) */
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_REAL_DENSITY"); mirvc.dens = e && *e ? (float)atof(e) : 1.25f;
    if (!(mirvc.dens >= 0.25f)) mirvc.dens = 0.25f;
    if (mirvc.dens > 4.0f) mirvc.dens = 4.0f;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_REAL_MSAA"); mirvc.msaa = e && *e ? atoi(e) : 4;
    mirvc.msaa = mirvc.msaa >= 8 ? 8 : mirvc.msaa >= 4 ? 4 : mirvc.msaa >= 2 ? 2 : 1;
    e = getenv("ACZ_VR_COCKPIT_MIRRORS_REAL_AB"); mirvc.ab = e ? atoi(e) : 0;
    if (mirvc.ab < 0) mirvc.ab = 0;
    e = getenv("ACZ_DEBUG_COCKPIT_MIRRORS_REAL"); mirvc.dbg = e ? atoi(e) : 0;
}
static int mirv_cfg_on(void) { mirv_cfg_init(); return mirvc.on; }
static int mirv_ab_off(void) {                   /* ACZ_VR_COCKPIT_MIRRORS_REAL_AB: the cube march's half of the in-run A/B */
    static int last = -1;
    if (!mirvc.ab) return 0;
    int ph = (int)((vk_mono_ns() / 1000000000ull / (u64)mirvc.ab) & 1u);
    if (ph != last) { last = ph; ps2_log("cockpit mirrors real view A/B: %s", ph ? "the cube march" : "the real view"); }
    return ph;
}
/* renderer -> graphics worker (a sequence lock): the map is wanted (a cockpit with mirrors in the cockpit view, a mirror
   in view in the last second) and the rear camera's frustum (tangents u0 u1 v0 v1: u = x right / depth, v = y up /
   depth in the rear view) and map size */
static struct { u32 ver; int want; float box[4]; u32 w, h; } mlv_pub;
volatile int ps2_vk_mlv_want;                   /* (the graphics worker's first test: mlv_pub.want, without the lock) */
static void mlv_pub_write(int want, const float box[4], u32 w, u32 h) {
    u32 v = __atomic_load_n(&mlv_pub.ver, __ATOMIC_RELAXED);
    ps2_vk_mlv_want = want;
    if (mlv_pub.want == want && mlv_pub.w == w && mlv_pub.h == h && !memcmp(mlv_pub.box, box, sizeof mlv_pub.box)) return;
    __atomic_store_n(&mlv_pub.ver, v + 1u, __ATOMIC_RELAXED);
    __atomic_thread_fence(__ATOMIC_RELEASE);
    mlv_pub.want = want; memcpy(mlv_pub.box, box, sizeof mlv_pub.box); mlv_pub.w = w; mlv_pub.h = h;
    __atomic_thread_fence(__ATOMIC_RELEASE);
    __atomic_store_n(&mlv_pub.ver, v + 2u, __ATOMIC_RELEASE);
}
static int mlv_pub_read(int *want, float box[4], u32 *w, u32 *h) {
    for (int tries = 0; tries < 8; tries++) {
        u32 v0 = __atomic_load_n(&mlv_pub.ver, __ATOMIC_ACQUIRE);
        if (v0 & 1u) continue;
        *want = mlv_pub.want; memcpy(box, mlv_pub.box, 4 * sizeof *box); *w = mlv_pub.w; *h = mlv_pub.h;
        __atomic_thread_fence(__ATOMIC_ACQUIRE);
        if (__atomic_load_n(&mlv_pub.ver, __ATOMIC_RELAXED) == v0) return 1;
    }
    return 0;
}
/* the renderer's side: the map (colour + depth, 2 layers with multiview: drawn by the frame's own multiview pipelines,
   no new pipeline states; layer 0 is sampled), its sampled views and sets (cockpit sets 8, 9), the game frame of the
   map now in it and that map's camera, the cockpit's last sight of a mirror */
static struct {
    VkImage cimg, dimg; VkDeviceMemory cmem, dmem;
    VkImageView crv, drv, csv, dsv;
    VkDescriptorSet cset, dset;
    VkSampler csmp, dsmp;
    u32 w, h, layers;
    VkImageLayout clay, dlay;
    const void *arena; u32 seq;
    int valid;
    float map[8];
    float zk[4];                       /* the map's depth: zA, zB, zscale, zmax (the model program's; mlv_cockpit) */
    float cam[9]; int cam_ok;          /* the game frame's own camera (no head, not extrapolated) the map was drawn with
                                          (mir_sharp: ACZ_VR_COCKPIT_MIRRORS_LIVE_TURN) */
    u64 vis_until, vram;
    u32 nmaps, ndraws, nfail;
    u64 t_ns;
} mlv;
static void mlvd_copy(VkCommandBuffer cmd, VkImage img, VkImageLayout lay, u32 w, u32 h, u32 slot);
static void mlvd_write(u32 field);
static void mirvd_write(u32 field);
static int mlv_terr_off(void) {                  /* ACZ_VR_COCKPIT_MIRRORS_TERRAIN_AB: the terrain's off half (in-run A/B) */
    static int ab = -1, last = -1;
    if (ab < 0) { const char *e = getenv("ACZ_VR_COCKPIT_MIRRORS_TERRAIN_AB"); ab = e ? atoi(e) : 0; if (ab < 0) ab = 0; }
    if (!ab) return 0;
    int ph = (int)((vk_mono_ns() / 1000000000ull / (u64)ab) & 1u);
    if (ph != last) { last = ph; ps2_log("cockpit mirrors terrain A/B: %s", ph ? "terrain off" : "terrain on"); }
    return ph;
}
static int mlv_ab_off(void) {                    /* ACZ_VR_COCKPIT_MIRRORS_LIVE_AB: the off half of the in-run A/B */
    static int last = -1;
    if (!mlvc.ab) return 0;
    int ph = (int)((vk_mono_ns() / 1000000000ull / (u64)mlvc.ab) & 1u);
    if (ph != last) { last = ph; ps2_log("cockpit mirrors live A/B: %s", ph ? "live map off" : "live map on"); }
    return ph;
}

static SDL_Window *window;
static char window_title[128];
static VkInstance inst;
static VkPhysicalDevice phys;
static VkDevice dev;
static VkQueue queue;
static u32 qfamily;
/* PS2_PERF_CLOUD_ASYNC (perf4_passes 2026-11-03; see cla_need): a second queue of the frame's family for our far cloud
   update, its timeline semaphore and the last value handed out (renderer thread) */
static VkQueue queue2;
static VkSemaphore cla_sem;
