/* VK_EXT_pipeline_creation_feedback (core 1.3), chained into pipe_build: [0] warm-up workers, [1] the renderer (on demand
   and the slice warm-up): states built, of them cache hits (APPLICATION_PIPELINE_CACHE_HIT; the NVIDIA driver counts
   its own shader cache's too: 190-219 of 246 states were hits into an empty VkPipelineCache), the driver's own time
   (ns). pipe_fb_last_*: the renderer's last build (get_pipeline_ex logs states built on demand). */
static u64 pipe_fb_n[2], pipe_fb_hit[2], pipe_fb_ns[2];
static int pipe_fb_last_hit = -1;
static double pipe_fb_last_ms;
static void pipe_feedback(int worker, const VkPipelineCreationFeedback *f, int ok) {
    int k = worker ? 0 : 1;
    int valid = ok && (f->flags & VK_PIPELINE_CREATION_FEEDBACK_VALID_BIT);
    int hit = valid && (f->flags & VK_PIPELINE_CREATION_FEEDBACK_APPLICATION_PIPELINE_CACHE_HIT_BIT);
    if (!worker) { pipe_fb_last_hit = valid ? hit : -1; pipe_fb_last_ms = valid ? (double)f->duration / 1e6 : 0.0; }
    if (!ok) return;
    __atomic_fetch_add(&pipe_fb_n[k], 1ull, __ATOMIC_RELAXED);
    if (hit) __atomic_fetch_add(&pipe_fb_hit[k], 1ull, __ATOMIC_RELAXED);
    if (valid) __atomic_fetch_add(&pipe_fb_ns[k], (u64)f->duration, __ATOMIC_RELAXED);
}
