    VkShaderModule vs, fs;
    VkPipelineLayout layout;
    VkPipeline pipe;
    VkBuffer vb[2], ib;
    VkDeviceMemory vm[2], im;
    void *vp[2], *ip;
    int cur, ok;
    u32 gen, nlog;
