            for (int i = 0; i < n; i++) {
                out[i].x = gx + (v[i].x - gx) * sd; out[i].y = gy + (v[i].y - gy) * sd;
                out[i].xr_dx = 0.0f; out[i].xr_iw = 0.0f;
                if (sd != 1.0f) out[i].round_uv = 0u;
            }
            xr_marker_roll(out, n, gx, gy);           /* (ACZ_VR_MARKER_ROLL) */
