    int i = cb_ring[s].n;
    memcpy(cb_ring[s].e[i].rows, rows, sizeof cb_ring[s].e[i].rows);
    memcpy(cb_ring[s].e[i].d, d, sizeof cb_ring[s].e[i].d);
    cb_ring[s].e[i].r = r;
    __atomic_store_n(&cb_ring[s].n, i + 1, __ATOMIC_RELEASE);
