        e = getenv("ACZ_VR_CLOUD_PERSP"); persp = on != 1 || (e && *e == '0') ? 0 : e && *e == 's' ? 2 : 1;
        e = getenv("ACZ_DEBUG_CLOUD_UPRIGHT"); dbg = e ? atoi(e) : 0;
